-- BledWay · Logos officiels transparents, pris sur le site de chaque compagnie.
-- Armas (dessiné dans sa page) et Corsica (fichier tout blanc, invisible sur fond clair) sont servis
-- depuis le site, recolorés dans la couleur de la marque.
UPDATE public.companies SET logo_url = '/logos/corsica-linea.png' WHERE name = 'Corsica Linea';
UPDATE public.companies SET logo_url = 'https://www.gnv.it/it/ck-static/logo.svg' WHERE name = 'GNV';
UPDATE public.companies SET logo_url = 'https://algerieferries.com/images/logo/logo%20pricipal.png' WHERE name = 'Algérie Ferries';
UPDATE public.companies SET logo_url = 'https://www.balearia.com/documents/20142/54842/Logo+Bale%C3%A0ria.png/0a6dffed-b734-2ef5-9197-ef6564c3908a?version=1.0&t=1656414631919&imagePreview=1' WHERE name = 'Baleària';
UPDATE public.companies SET logo_url = 'https://www.nouriselbahrferries.com/assets/logo-DqA9lwXf.png' WHERE name = 'Nouris Elbahr Ferries';
UPDATE public.companies SET logo_url = '/logos/armas-trasmediterranea.svg' WHERE name = 'Naviera Armas - Trasmediterránea';
